{"name":"tryActivate","qualified_name":"C-benchmark-codebase-memory-nest.packages.core.guards.guards-consumer.GuardsConsumer.tryActivate","label":"Method","file_path":"C:/benchmark/codebase-memory/nest/packages/core/guards/guards-consumer.ts","start_line":8,"end_line":35,"source":"  public async tryActivate<TContext extends string = ContextType>(
    guards: CanActivate[],
    args: unknown[],
    instance: Controller,
    callback: (...args: unknown[]) => unknown,
    type?: TContext,
  ): Promise<boolean> {
    if (!guards || isEmptyArray(guards)) {
      return true;
    }
    const context = this.createContext(args, instance, callback);
    context.setType<TContext>(type!);

    for (const guard of guards) {
      const result = guard.canActivate(context);
      if (typeof result === 'boolean') {
        if (!result) {
          return false;
        }
        continue;
      }
      if (await this.pickResult(result)) {
        continue;
      }
      return false;
    }
    return true;
  }
