{"name":"createPipesFn","qualified_name":"C-benchmark-codebase-memory-nest.packages.core.router.router-execution-context.RouterExecutionContext.createPipesFn","label":"Method","file_path":"C:/benchmark/codebase-memory/nest/packages/core/router/router-execution-context.ts","start_line":421,"end_line":456,"source":"  public createPipesFn(
    pipes: PipeTransform[],
    paramsOptions: (ParamProperties & { metatype?: any })[],
  ) {
    const pipesFn = async <TRequest, TResponse>(
      args: any[],
      req: TRequest,
      res: TResponse,
      next: Function,
    ) => {
      const resolveParamValue = async (
        param: ParamProperties & { metatype?: any },
      ) => {
        const {
          index,
          extractValue,
          type,
          data,
          metatype,
          pipes: paramPipes,
          schema,
        } = param;
        const value = extractValue(req, res, next);

        args[index] = this.isPipeable(type)
          ? await this.getParamValue(
              value,
              { metatype, type, data, schema } as ArgumentMetadata,
              pipes.concat(paramPipes),
            )
          : value;
      };
      await Promise.all(paramsOptions.map(resolveParamValue));
    };
    return paramsOptions.length ? pipesFn : null;
  }
