{"results":[{"node":"isHttpError","qualified_name":"C-benchmark-codebase-memory-nest.packages.core.exceptions.base-exception-filter.BaseExceptionFilter.isHttpError","label":"Method","file":"packages/core/exceptions/base-exception-filter.ts","start_line":88,"end_line":121,"in_degree":1,"out_degree":0,"match_lines":[88],"source":"  public isHttpError(err: any): err is { statusCode: number; message: string } {
    if (!err || typeof err !== 'object') {
      return false;
    }

    if (
      err.constructor?.name === 'FastifyError' &&
      typeof err.code === 'string' &&
      typeof err.statusCode === 'number'
    ) {
      return true;
    }

    // "http-errors" error signature
    if (
      typeof err.expose === 'boolean' &&
      typeof err.statusCode === 'number' &&
      err.status === err.statusCode &&
      err instanceof Error
    ) {
      return true;
    }

    // Plain "http error"-shaped values (e.g. non-Error objects thrown by third-party
    // middleware) that carry a valid HTTP status code and a message
    return (
      !(err instanceof Error) &&
      Number.isInteger(err.statusCode) &&
      err.statusCode >= 400 &&
      err.statusCode < 600 &&
      typeof err.message === 'string' &&
      err.message !== ''
    );
  }
